#!/usr/bin/env python3
"""Batch fix all autogenerated docstrings in v2/contacts.py."""

import re
from pathlib import Path

contacts_file = Path("src/britecore_sdk/api/api_calls/v2/contacts.py")
content = contacts_file.read_text(encoding="utf-8")

# Pattern to match "Autogenerated wrapper for ``POST /path``."
pattern = r'"""Autogenerated wrapper for ``([^`]+)``\."""'

def replace_func(match):
    path = match.group(1)
    endpoint = path.split("/")[-1]
    words = endpoint.replace("_", " ").title()

    return f'''"""{words}.
    
    Send a request to {path}. Returns processed result from
    ``process_result(...)`` and accepts ``RequestParameters`` overrides.
    
    Args:
        **kwargs: Additional request parameters (timeout, retry, headers, dry_run, etc.).
    
    Returns:
        Any: The processed response containing the requested data.
    
    Raises:
        BritecoreError: Various exceptions from process_result if the API returns an error.
    """'''

new_content = re.sub(pattern, replace_func, content)

# Count changes
original_count = len(re.findall(pattern, content))

if original_count > 0:
    contacts_file.write_text(new_content, encoding="utf-8")
    print(f"✓ contacts.py: {original_count} docstrings fixed")
else:
    print("No autogenerated wrappers found")

print(f"Total fixed: {original_count}")

